398	rocksdb::ColumnFamilyHandle *RocksdbContext::get_cf(
399	    const std::string &cf_name) {
400	  std::lock_guard<std::mutex> lock(mutex_);
401	  for (auto cf_handle : cf_handles_) {
402	    if (cf_handle->GetName() == cf_name) {
403	      return cf_handle;
404	    }
405	  }
406	  return nullptr;
407	}
