240	
241	void RocksdbContext::prepare_options(
242	    std::shared_ptr<rocksdb::MergeOperator> merge_op) {
243	  // Increase parallelism with default thread count (typically 16)
244	  create_opts_.IncreaseParallelism();
245	
246	  // Optimize for level-based compaction style with default setting
247	  create_opts_.OptimizeLevelStyleCompaction();
248	
249	  // TODO: enable compression?
250	
251	  // Setting this to 1 means that when a memtable is full, it will be flushed
252	  // to disk immediately rather than being merged with other memtables
253	  create_opts_.min_write_buffer_number_to_merge = 1;
254	
255	  // Set the block size for the arena memory allocator to 64KB, which controls
256	  // how much memory is allocated at a time for internal operations
257	  create_opts_.arena_block_size = 1024 * 64;
258	
259	  // Do not create LOG.old when reopen
260	  create_opts_.keep_log_file_num = 1;
261	
262	  // Warnings and errors only
263	  create_opts_.info_log_level = rocksdb::WARN_LEVEL;
264	
265	  rocksdb::BlockBasedTableOptions table_options;
266	
267	  // Turn on bloom filters
268	  table_options.filter_policy.reset(rocksdb::NewBloomFilterPolicy(10, false));
269	
270	  // Merge operator
271	  if (merge_op) {
272	    create_opts_.merge_operator = merge_op;
273	    create_opts_.max_successive_merges = 100;
274	    create_opts_.write_buffer_size = 8 << 20;
275	  }
276	
277	  // Create default cache
278	  table_options.block_cache = nullptr;
279	
280	  auto table_factory = NewBlockBasedTableFactory(table_options);
281	  create_opts_.table_factory.reset(table_factory);
282	
283	  // Enable statistics
284	  create_opts_.statistics = rocksdb::CreateDBStatistics();
285	
286	  // Disable external write buffer manager, let RocksDB manage it
287	  create_opts_.write_buffer_manager = nullptr;
288	
289	  // Reduce preallocation size for manifest file to 512KB to save disk space
290	  create_opts_.manifest_preallocation_size = 512 * 1024;
291	
292	  // Disable direct reads (use buffered I/O instead)
293	  create_opts_.use_direct_reads = false;
294	
295	  // Hash skip list memtable for prefix-based lookups
296	  if (enable_hash_skiplist_) {
297	    create_opts_.prefix_extractor.reset(rocksdb::NewCappedPrefixTransform(8));
298	    create_opts_.memtable_factory.reset(rocksdb::NewHashSkipListRepFactory(
299	        1000000,  // bucket_count
300	        4,        // skiplist_height
301	        4         // skiplist_branching_factor
302	        ));
303	    create_opts_.allow_concurrent_memtable_write = false;
304	    read_opts_.total_order_seek = true;
305	  }
306	}
