309	Status RocksdbContext::close() {
310	  std::lock_guard<std::mutex> lock(mutex_);
311	
312	  if (db_ == nullptr) {
313	    LOG_ERROR("RocksDB[%s] is not opened", db_path_.c_str());
314	    return Status::InternalError();
315	  }
316	
317	  if (!read_only_) {
318	    if (auto s = flush_unlocked(); !s.ok()) {
319	      LOG_ERROR("Failed to close RocksDB[%s] due to flush failure",
320	                db_path_.c_str());
321	      return s;
322	    }
323	  }
324	
325	  delete_cf_handles();
326	
327	  if (auto s = db_->Close(); s.ok()) {
328	    LOG_DEBUG("Closed RocksDB[%s]", db_path_.c_str());
329	    db_.reset();
330	    return Status::OK();
331	  } else {
332	    LOG_ERROR("Failed to close RocksDB[%s], code[%d], reason[%s]",
333	              db_path_.c_str(), s.code(), s.ToString().c_str());
334	    return Status::InternalError();
335	  }
336	}
337	
338	
339	Status RocksdbContext::flush_unlocked() {
340	  if (read_only_) {
341	    LOG_ERROR("Cannot flush RocksDB[%s] in read-only mode", db_path_.c_str());
342	    return Status::PermissionDenied();
343	  }
344	
345	  for (const auto &cf : cf_handles_) {
346	    if (auto s = db_->Flush(flush_opts_, cf); !s.ok()) {
347	      LOG_ERROR("Failed to flush cf[%s] of RocksDB[%s], code[%d], reason[%s]",
348	                cf->GetName().c_str(), db_path_.c_str(), s.code(),
349	                s.ToString().c_str());
350	      return Status::InternalError();
351	    }
352	  }
353	
354	  if (auto s = db_->Flush(flush_opts_); s.ok()) {
355	    LOG_DEBUG("Flushed RocksDB[%s]", db_path_.c_str());
356	    return Status::OK();
357	  } else {
358	    LOG_ERROR("Failed to flush Rocksdb[%s], code[%d], reason[%s]",
359	              db_path_.c_str(), s.code(), s.ToString().c_str());
360	    return Status::InternalError();
361	  }
362	}
363	
364	
365	Status RocksdbContext::flush() {
366	  std::lock_guard<std::mutex> lock(mutex_);
367	  return flush_unlocked();
368	}
