371	Status RocksdbContext::create_checkpoint(const std::string &checkpoint_dir) {
372	  std::lock_guard<std::mutex> lock(mutex_);
373	
374	  rocksdb::Checkpoint *cp{nullptr};
375	  if (auto s = rocksdb::Checkpoint::Create(db_.get(), &cp); !s.ok()) {
376	    LOG_ERROR(
377	        "Failed to create a checkpoint object of Rocksdb[%s], code[%d], "
378	        "reason[%s]",
379	        db_path_.c_str(), s.code(), s.ToString().c_str());
380	    return Status::InternalError();
381	  }
382	
383	  if (auto s = cp->CreateCheckpoint(checkpoint_dir); s.ok()) {
384	    LOG_DEBUG("Created a checkpoint of Rocksdb[%s] to [%s]", db_path_.c_str(),
385	              checkpoint_dir.c_str());
386	    delete cp;
387	    return Status::OK();
388	  } else {
389	    LOG_ERROR(
390	        "Failed to create a checkpoint of Rocksdb[%s], code[%d], reason[%s]",
391	        db_path_.c_str(), s.code(), s.ToString().c_str());
392	    delete cp;
393	    return Status::InternalError();
394	  }
395	}
