448	
449	Status RocksdbContext::drop_cf(const std::string &cf_name) {
450	  std::lock_guard<std::mutex> lock(mutex_);
451	
452	  if (cf_name == rocksdb::kDefaultColumnFamilyName) {
453	    LOG_ERROR("Forbidden to drop default cf in RocksDB[%s]", db_path_.c_str());
454	    return Status::InvalidArgument();
455	  }
456	
457	  auto it = std::find_if(cf_handles_.begin(), cf_handles_.end(),
458	                         [&cf_name](rocksdb::ColumnFamilyHandle *handle) {
459	                           return handle->GetName() == cf_name;
460	                         });
461	  if (it == cf_handles_.end()) {
462	    LOG_WARN("Failed to find column family[%s] in RocksDB[%s]", cf_name.c_str(),
463	             db_path_.c_str());
464	    return Status::OK();
465	  }
466	
467	  auto s = db_->DropColumnFamily(*it);
468	  if (s.ok()) {
469	    delete *it;
470	    cf_handles_.erase(it);
471	    LOG_DEBUG("Dropped cf[%s] in RocksDB[%s]", cf_name.c_str(),
472	              db_path_.c_str());
473	    return Status::OK();
474	  } else {
475	    LOG_ERROR("Failed to drop cf[%s] in RocksDB[%s], code[%d], reason[%s]",
476	              cf_name.c_str(), db_path_.c_str(), s.code(),
477	              s.ToString().c_str());
478	    return Status::InternalError();
479	  }
480	}
481	
482	
483	Status RocksdbContext::reset_cf(const std::string &cf_name) {
484	  std::lock_guard<std::mutex> lock(mutex_);
485	
486	  if (cf_name == rocksdb::kDefaultColumnFamilyName) {
487	    LOG_ERROR("Forbidden to reset default cf in RocksDB[%s]", db_path_.c_str());
488	    return Status::InvalidArgument();
489	  }
490	
491	  rocksdb::ColumnFamilyHandle *cf_handle{nullptr};
492	  size_t index = 0;
493	  for (size_t i = 0; i < cf_handles_.size(); ++i) {
494	    if (cf_handles_[i]->GetName() == cf_name) {
495	      cf_handle = cf_handles_[i];
496	      index = i;
497	      break;
498	    }
499	  }
500	  if (cf_handle == nullptr) {
501	    LOG_ERROR("Column family[%s] does not exist in RocksDB[%s]",
502	              cf_name.c_str(), db_path_.c_str());
503	    return Status::InvalidArgument();
504	  }
505	
506	  auto options = db_->GetOptions(cf_handle);
507	  auto s = db_->DropColumnFamily(cf_handle);
508	  if (!s.ok()) {
509	    LOG_ERROR("Failed to drop cf[%s] in RocksDB[%s], code[%d], reason[%s]",
510	              cf_name.c_str(), db_path_.c_str(), s.code(),
511	              s.ToString().c_str());
512	    return Status::InternalError();
513	  }
514	  delete cf_handle;
515	
516	  rocksdb::ColumnFamilyHandle *new_cf_handle{nullptr};
517	  s = db_->CreateColumnFamily(options, cf_name, &new_cf_handle);
518	  if (s.ok()) {
519	    cf_handles_[index] = new_cf_handle;
520	    LOG_DEBUG("Reset cf[%s] in RocksDB[%s]", cf_name.c_str(), db_path_.c_str());
521	    return Status::OK();
522	  } else {
523	    LOG_ERROR("Failed to create cf[%s] in RocksDB[%s], code[%d], reason[%s]",
524	              cf_name.c_str(), db_path_.c_str(), s.code(),
525	              s.ToString().c_str());
526	    return Status::InternalError();
527	  }
528	}
529	
530	
531	void RocksdbContext::delete_cf_handles() {
532	  for (auto cf : cf_handles_) {
533	    db_->DestroyColumnFamilyHandle(cf);
534	  }
535	  cf_handles_.clear();
536	}
