538	
539	Status RocksdbContext::compact() {
540	  std::lock_guard<std::mutex> lock(mutex_);
541	
542	  for (auto cf : cf_handles_) {
543	    auto s = db_->CompactRange(compact_range_opts_, cf, nullptr, nullptr);
544	    if (!s.ok()) {
545	      LOG_ERROR("Failed to compact cf[%s] in RocksDB[%s], code[%d], reason[%s]",
546	                cf->GetName().c_str(), db_path_.c_str(), s.code(),
547	                s.ToString().c_str());
548	    }
549	  }
550	  auto s = db_->CompactRange(compact_range_opts_, nullptr, nullptr);
551	  if (s.ok()) {
552	    LOG_DEBUG("Compacted RocksDB[%s]", db_path_.c_str());
553	    return Status::OK();
554	  } else {
555	    LOG_ERROR("Failed to compact RocksDB[%s], code[%d], reason[%s]",
556	              db_path_.c_str(), s.code(), s.ToString().c_str());
557	    return Status::InternalError();
558	  }
559	}
